  "knowledge": "Audit Finding Severity (AFS)",
  "description": "Quantifies the severity of audit findings based on critical findings.",
  "definition": "AFS = \\frac{\\text{CritFindNum}}{\\text{FindTally} + 1}"
}

{
  "id": 8,
  "knowledge": "Data Subject Request Load (DSRL)",
  "description": "Measures the workload from data subject requests.",
  "definition": "DSRL = \\text{AccReqNum} + \\text{DelReqNum} + \\text{RectReqNum} + \\text{PortReqNum}"
}

{
  "id": 36,
  "knowledge": "Audit Remediation Load (ARL)",
  "description": "Calculates the workload required for audit remediation based on findings and compliance gaps.",
  "definition": "ARL = \\text{AFS} \\times \\text{DSRL}"
}

